import { describe, expect, test } from 'bun:test'
import { commandsAfter, configValue, extrusions, featureLengths, firstExtrusionLine, layerAtLine, layerBounds, layerHitsRect, scanGcode, segmentHitsRect, splitLines } from '../scripts/lib/gcode.ts'

// The shape Orca writes for a plain (non-Bambu) printer: tags, Z move, custom G-code, extrusions.
const PLAIN = [
  '; generated by OrcaSlicer',
  'G90',
  'M83',
  ';LAYER_CHANGE',
  ';Z:0.25',
  ';HEIGHT:0.25',
  'G1 Z0.25 F600',
  'G1 X0 Y0 F9000',
  'G1 X10 Y0 E0.5',
  'G1 X10 Y10 E0.5',
  'G1 E-0.8 F2100 ; retract',
  'G1 X0 Y10',
  ';LAYER_CHANGE',
  ';Z:0.45',
  ';HEIGHT:0.2',
  'G1 Z0.45',
  ';PAUSE_PRINT',
  'PAUSE',
  'M73 P50 R10',
  'G1 E0.8',
  'G1 X0 Y0 E0.4',
  ';CUSTOM_GCODE',
  'M117 hello',
  '',
].join('\n')

describe('scanGcode', () => {
  test('finds plain layer changes with their Z and height, pauses and custom blocks', () => {
    const s = scanGcode(PLAIN)
    expect(s.style).toBe('plain')
    expect(s.layers).toEqual([
      { index: 0, z: 0.25, height: 0.25, line: 3 },
      { index: 1, z: 0.45, height: 0.2, line: 12 },
    ])
    expect(s.pauses).toEqual([16])
    expect(s.customs).toEqual([21])
  })

  test('reads Bambu tags and CRLF line endings', () => {
    const text = ['; CHANGE_LAYER', '; Z_HEIGHT: 0.2', '; LAYER_HEIGHT: 0.2', 'G1 Z.2', '; PAUSE_PRINTING', 'M400 U1', '; CHANGE_LAYER', '; Z_HEIGHT: 0.4', '; LAYER_HEIGHT: 0.2', '; CUSTOM_GCODE'].join('\r\n')
    const s = scanGcode(text)
    expect(s.style).toBe('bbl')
    expect(s.layers.map((l) => [l.z, l.height, l.line])).toEqual([
      [0.2, 0.2, 0],
      [0.4, 0.2, 6],
    ])
    expect(s.pauses).toEqual([4])
    expect(s.customs).toEqual([9])
    expect(s.lines[1]).toBe('; Z_HEIGHT: 0.2')
  })

  test("an empty layer never takes the next layer's tags", () => {
    const s = scanGcode([';LAYER_CHANGE', ';Z:0.2', ';HEIGHT:0.2', ';LAYER_CHANGE', ';Z:0.4', ';HEIGHT:0.2'].join('\n'))
    expect(s.layers.map((l) => l.z)).toEqual([0.2, 0.4])
    expect(() => scanGcode([';LAYER_CHANGE', ';HEIGHT:0.2', ';LAYER_CHANGE', ';Z:0.4'].join('\n'))).toThrow(/line 1: a layer change without its Z tag/)
  })

  test('a layer change without its Z tag is refused', () => {
    expect(() => scanGcode(';LAYER_CHANGE\nG1 Z1\nG1 X1\nG1 X2\nG1 X3\nG1 X4\nG1 X5\n;Z:1')).toThrow(/line 1: a layer change without its Z tag/)
  })

  test('splitLines keeps empty lines and drops carriage returns', () => {
    expect(splitLines('a\r\nb\n\nc')).toEqual(['a', 'b', '', 'c'])
  })
})

describe('layers and commands', () => {
  const s = scanGcode(PLAIN)

  test('layerAtLine: the last layer change at or before a line', () => {
    expect(layerAtLine(s, 0)).toBeUndefined()
    expect(layerAtLine(s, 3)?.index).toBe(0)
    expect(layerAtLine(s, 11)?.index).toBe(0)
    expect(layerAtLine(s, 12)?.index).toBe(1)
    expect(layerAtLine(s, 100)?.index).toBe(1)
  })

  test('commandsAfter skips comments, blank lines and M73 progress', () => {
    expect(commandsAfter(s.lines, 16, 2)).toEqual(['PAUSE', 'G1 E0.8'])
    expect(commandsAfter(['; x', '', 'M73 P1', 'G1 X1 ; move', 'M400'], -1, 5)).toEqual(['G1 X1', 'M400'])
  })

  test("configValue reads a setting from the config block only, as Orca writes it ('; key = value')", () => {
    const lines = splitLines(
      [
        '; z_offset = 9 ; a comment line before the block, not the setting',
        'G1 X1',
        '; CONFIG_BLOCK_START',
        '; required_nozzle_HRC = 5',
        '; z_offset = -0.1',
        '; z_offset_extra = 7',
        '; machine_pause_gcode = PAUSE\\nM400',
        '; filament_notes = ',
        '; CONFIG_BLOCK_END',
        '; layer_height = 0.3',
        '',
      ].join('\r\n'),
    )
    expect(configValue(lines, 'z_offset')).toBe('-0.1')
    expect(configValue(lines, 'required_nozzle_HRC')).toBe('5')
    expect(configValue(lines, 'z_offset_extra')).toBe('7')
    expect(configValue(lines, 'machine_pause_gcode')).toBe('PAUSE\\nM400')
    expect(configValue(lines, 'filament_notes')).toBe('')
    expect(configValue(lines, 'layer_height')).toBeUndefined()
    expect(configValue(lines, 'required_nozzle_hrc')).toBeUndefined()
    expect(configValue(s.lines, 'z_offset')).toBeUndefined()
  })
})

describe('extrusions', () => {
  test('relative E: extruding moves only, with their layer; retracts and travels are not extrusions', () => {
    const s = scanGcode(PLAIN)
    const ex = extrusions(s)
    expect(ex.map((e) => [e.line, e.layer, e.x0, e.y0, e.x1, e.y1])).toEqual([
      [8, 0, 0, 0, 10, 0],
      [9, 0, 10, 0, 10, 10],
      [20, 1, 0, 10, 0, 0],
    ])
    expect(firstExtrusionLine(ex, 1)).toBe(20)
    expect(firstExtrusionLine(ex, 0, 9)).toBe(9)
    expect(firstExtrusionLine(ex, 5)).toBeUndefined()
    expect(layerBounds(ex, 0)).toEqual({ minX: 0, minY: 0, maxX: 10, maxY: 10 })
    expect(layerBounds(ex, 3)).toBeUndefined()
  })

  test('absolute E with G92 resets, and relative XY under G91', () => {
    const text = [
      ';LAYER_CHANGE',
      ';Z:0.2',
      'G90',
      'M82',
      'G92 E0',
      'G1 X5 Y5',
      'G1 X6 Y5 E1.0',
      'G1 X7 Y5 E0.9', // E going down: a retract, not an extrusion
      'G1 X8 Y5 E1.5',
      'G92 E0',
      'G1 X9 Y5 E0.2',
      'G91',
      'G1 X1 Y1 E0.1',
      'G90',
      'G1 X20 Y20',
    ].join('\n')
    const ex = extrusions(scanGcode(text))
    expect(ex.map((e) => [e.x0, e.y0, e.x1, e.y1])).toEqual([
      [5, 5, 6, 5],
      [7, 5, 8, 5],
      [8, 5, 9, 5],
      [9, 5, 10, 6],
    ])
    expect(ex.every((e) => e.layer === 0)).toBe(true)
  })

  test('each extrusion has the Z the G-code moved to: G1 Z, lifts and their return, G91, G92 Z and helical arcs', () => {
    const text = [
      'M83',
      'G1 X5 Y0 E1 ; before any Z move',
      ';LAYER_CHANGE',
      ';Z:0.25',
      'G1 Z.55 F600', // print Z 0.25 with a z_offset of 0.3
      'G1 X10 Y0 E0.5',
      'G1 Z.95 F21000 ; lift',
      'G1 X20 Y20',
      'G1 Z.55 ; back down',
      'G1 X20 Y30 E0.5',
      'G91',
      'G1 Z0.25',
      'G1 X1 Y0 E0.1',
      'G90',
      'M83',
      'G92 Z10',
      'G1 X30 Y30 E0.1',
      'G1 X40 Y30 Z10.5 E0.1',
      'G3 X40 Y50 I0 J10 Z11.5 E1',
    ].join('\n')
    const ex = extrusions(scanGcode(text))
    expect(ex.slice(0, 6).map((e) => [e.line, e.layer, e.z])).toEqual([
      [1, -1, 0],
      [5, 0, 0.55],
      [9, 0, 0.55],
      [12, 0, 0.8],
      [16, 0, 10],
      [17, 0, 10.5],
    ])
    // A half circle as 18 chords of 10 degrees, climbing evenly from 10.5 to 11.5.
    const arc = ex.slice(6)
    expect(arc).toHaveLength(18)
    arc.forEach((e, i) => expect(e.z).toBeCloseTo(10.5 + (i + 1) / 18, 9))
    expect(arc[17]!.z).toBe(11.5)
  })

  test('moves before the first layer change belong to layer -1', () => {
    const ex = extrusions(scanGcode(['M83', 'G1 X0 Y0', 'G1 X50 Y0 E2 ; purge line', ';LAYER_CHANGE', ';Z:0.2', 'G1 X50 Y5 E0.2'].join('\n')))
    expect(ex.map((e) => e.layer)).toEqual([-1, 0])
  })

  test('arcs become chords of at most 10 degrees on the circle', () => {
    // Counter-clockwise quarter circle around (0, 0) from (10, 0) to (0, 10).
    const ccw = extrusions(scanGcode(['M83', ';LAYER_CHANGE', ';Z:0.2', 'G1 X10 Y0', 'G3 X0 Y10 I-10 J0 E1'].join('\n')))
    expect(ccw).toHaveLength(9)
    expect([ccw[0]!.x0, ccw[0]!.y0]).toEqual([10, 0])
    expect([ccw[8]!.x1, ccw[8]!.y1]).toEqual([0, 10])
    for (const e of ccw) {
      expect(Math.hypot(e.x1, e.y1)).toBeCloseTo(10, 9)
      expect(e.y1).toBeGreaterThanOrEqual(-1e-9) // stays in the first quadrant
    }
    // Clockwise: from (0, 10) to (10, 0) around (0, 0), through the first quadrant again.
    const cw = extrusions(scanGcode(['M83', ';LAYER_CHANGE', ';Z:0.2', 'G1 X0 Y10', 'G2 X10 Y0 I0 J-10 E1'].join('\n')))
    expect(cw).toHaveLength(9)
    for (const e of cw) {
      expect(e.x1).toBeGreaterThanOrEqual(-1e-9)
      expect(e.y1).toBeGreaterThanOrEqual(-1e-9)
    }
  })
})

describe('rectangles', () => {
  const r = { minX: 0, minY: 0, maxX: 10, maxY: 10 }

  test('segmentHitsRect: through, inside, outside and along an edge', () => {
    expect(segmentHitsRect(-5, 5, 15, 5, r)).toBe(true)
    expect(segmentHitsRect(2, 2, 3, 3, r)).toBe(true)
    expect(segmentHitsRect(-5, -5, -1, 20, r)).toBe(false)
    expect(segmentHitsRect(11, -1, 11, 20, r)).toBe(false)
    expect(segmentHitsRect(-5, 12, 15, 12, r)).toBe(false)
    expect(segmentHitsRect(-1, 8, 2, 11, r)).toBe(true) // clips the corner
    expect(segmentHitsRect(-5, 11, 1, 17, r)).toBe(false) // passes the corner outside
  })

  test('layerHitsRect looks only at the given layer', () => {
    const ex = extrusions(scanGcode(PLAIN))
    expect(layerHitsRect(ex, 0, { minX: 4, minY: -1, maxX: 6, maxY: 1 })).toBe(true)
    expect(layerHitsRect(ex, 1, { minX: 4, minY: -1, maxX: 6, maxY: 1 })).toBe(false)
    expect(layerHitsRect(ex, 1, { minX: -1, minY: 4, maxX: 1, maxY: 6 })).toBe(true)
  })
})

describe('featureLengths', () => {
  test('sums the XY length of each feature from its tag, in both tag styles, arcs measured along the arc', () => {
    const plain = [
      'G90',
      'M83',
      ';LAYER_CHANGE',
      ';Z:0.2',
      'G1 X0 Y0',
      'G1 X5 Y0 E0.1',
      ';TYPE:Outer wall',
      'G1 X10 Y0 E0.2',
      'G1 X10 Y10 E0.2',
      ';TYPE:Inner wall',
      'G1 X10 Y13 E0.1',
      'G1 X14 Y13 E0.1',
      'G1 X20 Y20',
      ';TYPE:Outer wall',
      'G1 X20 Y25 E0.1',
      '',
    ].join('\n')
    const moves = extrusions(scanGcode(plain))
    expect(moves[0]!.role).toBeUndefined()
    expect(moves[1]!.role).toBe('Outer wall')
    expect(Object.fromEntries(featureLengths(moves))).toEqual({ 'Outer wall': 20, 'Inner wall': 7 })

    const bbl = ['G90', 'M83', '; CHANGE_LAYER', '; Z_HEIGHT: 0.2', '; FEATURE: Outer wall', 'G1 X10 Y0', 'G3 X-10 Y0 I-10 J0 E1', ''].join('\n')
    const half = featureLengths(extrusions(scanGcode(bbl))).get('Outer wall')!
    // Half a circle of radius 10, as chords of at most 10 degrees.
    expect(half).toBeGreaterThan(31.3)
    expect(half).toBeLessThan(Math.PI * 10)
  })
})
